levels.reference_solution:
def parse_users(rows: list[dict[str, object]]) -> list[str]:
    """Extract normalized active user emails."""
    if not rows:
        return []
    return [
        str(row["email"]).strip().lower()
        for row in rows
        if row.get("active") and row.get("email")
    ]
